## 🔍 Detalhes Técnicos

### Configuração `vitest.config.js`

```javascript
import { defineConfig } from 'vitest/config';

export default defineConfig({
    test: {
        globals: true,
        environment: 'node',
        include: ['test/unit/**/*.test.js'],
        coverage: {
            provider: 'v8',
            reporter: ['text', 'lcov'],
            include: ['src/**/*.js'],
            exclude: ['src/server.js'], // Too large for unit testing
        },
        testTimeout: 10000,
    },
});
```

