#!/usr/bin/env node
/**
 * OmniAntigravity Remote Chat — Trusted HTTPS Setup
 * 
 * Automatically installs mkcert, creates a local CA, and generates
 * trusted SSL certificates. After this, browsers will show the green
 * padlock with zero warnings.
 * 
 * Usage: node scripts/setup-ssl.js
 *
 * Supports: Linux (apt/pacman/dnf), macOS (brew), Windows (choco/scoop)
 */
import { execSync } from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = path.join(__dirname, '..');
const certsDir = path.join(PROJECT_ROOT, 'certs');

const c = {
    reset: '\x1b[0m', bold: '\x1b[1m', dim: '\x1b[2m',
    green: '\x1b[32m', red: '\x1b[31m', yellow: '\x1b[33m',
    cyan: '\x1b[36m', magenta: '\x1b[35m',
};

function log(msg) { console.log(`  ${msg}`); }
function ok(msg) { log(`${c.green}✓${c.reset} ${msg}`); }
function warn(msg) { log(`${c.yellow}⚠${c.reset} ${msg}`); }
function fail(msg) { log(`${c.red}✗${c.reset} ${msg}`); }
function info(msg) { log(`${c.cyan}ℹ${c.reset} ${msg}`); }

function run(cmd, opts = {}) {
    try {
        return execSync(cmd, { encoding: 'utf8', stdio: 'pipe', ...opts }).trim();
    } catch (e) {
        return null;
    }
}

function hasBinary(name) {
    const cmd = process.platform === 'win32' ? `where ${name}` : `which ${name}`;
    return run(cmd) !== null;
}

function getLocalIPs() {
    const ips = ['localhost', '127.0.0.1'];
    const interfaces = os.networkInterfaces();
    for (const name of Object.keys(interfaces)) {
        for (const iface of interfaces[name]) {
            if (iface.family === 'IPv4' && !iface.internal) {
                ips.push(iface.address);
            }
        }
    }
    return [...new Set(ips)];
}

// ─── Step 1: Check if mkcert is installed ─────────────────────────
function checkMkcert() {
    if (hasBinary('mkcert')) {
        ok('mkcert is installed');
        return true;
    }
    return false;
}

// ─── Step 2: Install mkcert ───────────────────────────────────────
function installMkcert() {
    const platform = process.platform;

    console.log('');
    warn('mkcert is not installed. Attempting automatic installation...\n');

    if (platform === 'linux') {
        // Try apt (Ubuntu/Debian)
        if (hasBinary('apt-get')) {
            info('Detected apt (Ubuntu/Debian)');
            try {
                execSync('sudo apt-get update -qq && sudo apt-get install -y -qq mkcert', { stdio: 'inherit' });
                return true;
            } catch { /* fall through */ }
        }
        // Try pacman (Arch)
        if (hasBinary('pacman')) {
            info('Detected pacman (Arch)');
            try {
                execSync('sudo pacman -S --noconfirm mkcert', { stdio: 'inherit' });
                return true;
            } catch { /* fall through */ }
        }
        // Try dnf (Fedora)
        if (hasBinary('dnf')) {
            info('Detected dnf (Fedora/RHEL)');
            try {
                execSync('sudo dnf install -y mkcert', { stdio: 'inherit' });
                return true;
            } catch { /* fall through */ }
        }
    } else if (platform === 'darwin') {
        if (hasBinary('brew')) {
            info('Detected Homebrew (macOS)');
            try {
                execSync('brew install mkcert', { stdio: 'inherit' });
                return true;
            } catch { /* fall through */ }
        }
    } else if (platform === 'win32') {
        if (hasBinary('choco')) {
            info('Detected Chocolatey (Windows)');
            try {
                execSync('choco install mkcert -y', { stdio: 'inherit' });
                return true;
            } catch { /* fall through */ }
        }
        if (hasBinary('scoop')) {
            info('Detected Scoop (Windows)');
            try {
                execSync('scoop install mkcert', { stdio: 'inherit' });
                return true;
            } catch { /* fall through */ }
        }
    }

    // Manual installation instructions
    console.log('');
    fail('Could not install mkcert automatically.\n');
    console.log(`${c.bold}  Manual installation:${c.reset}\n`);

    if (platform === 'linux') {
        console.log('    Ubuntu/Debian:  sudo apt install mkcert');
        console.log('    Arch:           sudo pacman -S mkcert');
        console.log('    Fedora:         sudo dnf install mkcert');
    } else if (platform === 'darwin') {
        console.log('    brew install mkcert');
    } else if (platform === 'win32') {
        console.log('    choco install mkcert');
        console.log('    # or');
        console.log('    scoop install mkcert');
    }

    console.log(`\n    Then re-run: ${c.cyan}node scripts/setup-ssl.js${c.reset}\n`);
    return false;
}

// ─── Step 3: Install local CA ─────────────────────────────────────
function installCA() {
    info('Installing local Certificate Authority...');
    try {
        execSync('mkcert -install', { stdio: 'inherit' });
        ok('Local CA installed in system + browser trust stores');
        return true;
    } catch (e) {
        fail(`CA installation failed: ${e.message}`);
        return false;
    }
}

// ─── Step 4: Generate certificates ────────────────────────────────
function generateCerts() {
    const ips = getLocalIPs();
    info(`Generating certificate for: ${ips.join(', ')}`);

    // Create certs directory
    if (!fs.existsSync(certsDir)) {
        fs.mkdirSync(certsDir, { recursive: true });
    }

    const keyFile = path.join(certsDir, 'server.key');
    const certFile = path.join(certsDir, 'server.cert');

    try {
        execSync(
            `mkcert -key-file "${keyFile}" -cert-file "${certFile}" ${ips.join(' ')}`,
            { stdio: 'inherit' }
        );
        ok('Trusted SSL certificates generated!');
        return true;
    } catch (e) {
        fail(`Certificate generation failed: ${e.message}`);
        return false;
    }
}

// ─── Main ─────────────────────────────────────────────────────────
function main() {
    console.log('');
    console.log(`${c.magenta}${c.bold}  ╔══════════════════════════════════════════╗${c.reset}`);
    console.log(`${c.magenta}${c.bold}  ║  OmniAntigravity — Trusted HTTPS Setup  ║${c.reset}`);
    console.log(`${c.magenta}${c.bold}  ╚══════════════════════════════════════════╝${c.reset}`);
    console.log('');

    // Step 1: Check/install mkcert
    if (!checkMkcert()) {
        if (!installMkcert()) {
            process.exit(1);
        }
        if (!hasBinary('mkcert')) {
            fail('mkcert still not found after installation attempt');
            process.exit(1);
        }
        ok('mkcert installed successfully');
    }

    // Step 2: Install CA
    if (!installCA()) {
        process.exit(1);
    }

    // Step 3: Generate certs
    if (!generateCerts()) {
        process.exit(1);
    }

    // Done!
    console.log('');
    console.log(`${c.bold}─────────────────────────────────────────────${c.reset}`);
    console.log(`  ${c.green}${c.bold}✓ HTTPS setup complete!${c.reset}`);
    console.log(`  ${c.dim}Certificates: certs/server.key + certs/server.cert${c.reset}`);
    console.log(`${c.bold}─────────────────────────────────────────────${c.reset}`);
    console.log('');
    console.log(`  ${c.cyan}Start the server:${c.reset} npm start`);
    console.log(`  ${c.dim}It will auto-detect the certs and use HTTPS.${c.reset}`);
    console.log('');

    // Mobile instructions
    console.log(`  ${c.yellow}${c.bold}📱 For phones (optional):${c.reset}`);
    console.log(`  ${c.dim}Phones need the CA certificate installed manually.${c.reset}`);

    const caRoot = run('mkcert -CAROOT');
    if (caRoot) {
        const caFile = path.join(caRoot, 'rootCA.pem');
        if (fs.existsSync(caFile)) {
            console.log(`  ${c.dim}CA file: ${caFile}${c.reset}`);
            console.log('');
            console.log(`  ${c.bold}Android:${c.reset}`);
            console.log(`    1. Transfer ${c.cyan}rootCA.pem${c.reset} to your phone`);
            console.log(`    2. Settings → Security → Install certificate`);
            console.log(`    3. Select the rootCA.pem file`);
            console.log('');
            console.log(`  ${c.bold}iOS:${c.reset}`);
            console.log(`    1. Transfer ${c.cyan}rootCA.pem${c.reset} to your phone`);
            console.log(`    2. Settings → Profile Downloaded → Install`);
            console.log(`    3. Settings → General → About → Certificate Trust`);
            console.log(`    4. Enable trust for the mkcert root CA`);
        }
    }
    console.log('');
}

main();

function formatBytes(bytes) {
  if (!Number.isFinite(bytes) || bytes < 1024) return `${bytes || 0} B`;
  const units = ['KB', 'MB', 'GB'];
  let value = bytes / 1024;
  let index = 0;
  while (value >= 1024 && index < units.length - 1) {
    value /= 1024;
    index += 1;
  }
  return `${value.toFixed(value < 10 ? 1 : 0)} ${units[index]}`;
}

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

export class FileBrowser {
  constructor(root, { fetchWithAuth, notify }) {
    this.root = root;
    this.fetchWithAuth = fetchWithAuth;
    this.notify = notify;
    this.currentPath = '.';
    this.currentFile = '';
    this.renderShell();
  }

  renderShell() {
    this.root.innerHTML = `
      <div class="workspace-section split-card">
        <div class="workspace-card file-browser-layout">
          <div class="panel-header">
            <div>
              <div class="panel-title">File Browser</div>
              <div class="panel-subtitle" id="fileBrowserPath">Workspace root</div>
            </div>
            <div class="screen-actions">
              <button class="panel-btn" id="fileBrowserUpBtn">Up</button>
              <button class="panel-btn" id="fileBrowserRefreshBtn">Refresh</button>
            </div>
          </div>
          <div class="file-browser-main">
            <div class="file-list" id="fileBrowserEntries"></div>
          </div>
        </div>
        <div class="workspace-card">
          <div class="panel-header">
            <div>
              <div class="panel-title">Preview</div>
              <div class="panel-subtitle" id="fileBrowserPreviewLabel">Select a file</div>
            </div>
          </div>
          <pre class="code-preview"><code id="fileBrowserPreview">Choose a file from the list to inspect its contents.</code></pre>
        </div>
      </div>
    `;

    this.pathLabel = this.root.querySelector('#fileBrowserPath');
    this.entriesNode = this.root.querySelector('#fileBrowserEntries');
    this.previewLabel = this.root.querySelector('#fileBrowserPreviewLabel');
    this.previewNode = this.root.querySelector('#fileBrowserPreview');

    this.root
      .querySelector('#fileBrowserRefreshBtn')
      .addEventListener('click', () => this.loadDirectory(this.currentPath));
    this.root
      .querySelector('#fileBrowserUpBtn')
      .addEventListener('click', () => this.goUp());
  }

  async init() {
    await this.loadDirectory('.');
  }

  goUp() {
    if (this.currentPath === '.') return;
    const parts = this.currentPath.split('/').filter(Boolean);
    parts.pop();
    const nextPath = parts.length ? parts.join('/') : '.';
    this.loadDirectory(nextPath);
  }

  async loadDirectory(path = '.') {
    try {
      const response = await this.fetchWithAuth(
        `/api/fs/ls?path=${encodeURIComponent(path)}`
      );
      const payload = await response.json();
      this.currentPath = payload.path || '.';
      this.pathLabel.textContent = this.currentPath === '.' ? payload.root : this.currentPath;

      if (!payload.entries?.length) {
        this.entriesNode.innerHTML =
          '<div class="workspace-empty">This folder is empty.</div>';
        return;
      }

      this.entriesNode.innerHTML = payload.entries
        .map(
          (entry) => `
            <div class="file-entry ${this.currentFile === entry.path ? 'active' : ''}">
              <button type="button" data-path="${entry.path}" data-type="${entry.type}">
                <strong>${entry.type === 'directory' ? '▸' : '•'} ${escapeHtml(entry.name)}</strong>
                <div class="file-entry-meta">
                  ${entry.type === 'directory' ? 'Folder' : `${escapeHtml(entry.extension || 'file')} · ${formatBytes(entry.size)}`}
                </div>
              </button>
            </div>
          `
        )
        .join('');

      this.entriesNode.querySelectorAll('button[data-path]').forEach((button) => {
        button.addEventListener('click', () => {
          const nextPath = button.getAttribute('data-path') || '.';
          const type = button.getAttribute('data-type');
          if (type === 'directory') {
            this.loadDirectory(nextPath);
          } else {
            this.openFile(nextPath);
          }
        });
      });
    } catch (error) {
      this.notify(`Failed to load directory: ${error.message}`, 'error');
    }
  }

  async openFile(path) {
    try {
      const response = await this.fetchWithAuth(
        `/api/fs/cat?path=${encodeURIComponent(path)}`
      );
      const payload = await response.json();
      this.currentFile = path;
      this.previewLabel.textContent = `${payload.path}${payload.truncated ? ' · truncated' : ''}`;
      this.previewNode.className = `language-${payload.language || 'clike'}`;
      this.previewNode.textContent = payload.content;
      if (window.Prism?.highlightElement) {
        window.Prism.highlightElement(this.previewNode);
      }
      await this.loadDirectory(this.currentPath);
    } catch (error) {
      this.notify(`Failed to read file: ${error.message}`, 'error');
    }
  }
}

// @ts-check
/**
 * CDP connection management — discovery, connection, and initialization.
 *
 * @module cdp/connection
 */

import WebSocket from 'ws';
import { PORTS, EXCLUDED_TARGET_TITLES, CDP_CALL_TIMEOUT } from '../config.js';
import { getJson } from '../utils/network.js';
import * as state from '../state.js';

/**
 * Find a single Antigravity CDP endpoint (first workbench window found).
 *
 * @returns {Promise<{port: number, url: string}>}
 * @throws {Error} If no CDP target found on any port
 */
export async function discoverCDP() {
    const errors = [];
    for (const port of PORTS) {
        try {
            const list = await getJson(`http://127.0.0.1:${port}/json/list`);

            // Priority 1: Standard Workbench
            const workbench = list.find(t => t.url?.includes('workbench.html') || (t.title && t.title.includes('workbench')));
            if (workbench?.webSocketDebuggerUrl) {
                console.log('Found Workbench target:', workbench.title);
                return { port, url: workbench.webSocketDebuggerUrl };
            }

            // Priority 2: Jetski/Launchpad (Fallback)
            const jetski = list.find(t => t.url?.includes('jetski') || t.title === 'Launchpad');
            if (jetski?.webSocketDebuggerUrl) {
                console.log('Found Jetski/Launchpad target:', jetski.title);
                return { port, url: jetski.webSocketDebuggerUrl };
            }
        } catch (e) {
            errors.push(`${port}: ${/** @type {Error} */(e).message}`);
        }
    }
    throw new Error(`CDP not found. ${errors.length ? `Errors: ${errors.join(', ')}` : 'No ports responding'}`);
}

/**
 * Discover ALL available CDP targets across all ports (multi-window).
 * Only includes real editor workbench windows.
 *
 * @returns {Promise<import('../state.js').CDPTarget[]>}
 */
export async function discoverAllCDP() {
    /** @type {import('../state.js').CDPTarget[]} */
    const allTargets = [];

    for (const port of PORTS) {
        try {
            const list = await getJson(`http://127.0.0.1:${port}/json/list`);
            for (const t of list) {
                if (!t.webSocketDebuggerUrl) continue;

                const isWorkbench = t.url?.includes('workbench.html') && !t.url?.includes('jetski');
                if (!isWorkbench) continue;

                const titleLower = (t.title || '').toLowerCase();
                if (EXCLUDED_TARGET_TITLES.some(ex => titleLower === ex)) continue;

                allTargets.push({
                    id: `${port}:${t.id}`,
                    port,
                    title: t.title || 'Untitled',
                    url: t.url,
                    wsUrl: t.webSocketDebuggerUrl,
                    type: 'workbench'
                });
            }
        } catch (_) { /* port not responding */ }
    }
    return allTargets;
}

/**
 * Connect to a CDP WebSocket endpoint and enable Runtime.
 *
 * @param {string} url - WebSocket debugger URL
 * @returns {Promise<import('../state.js').CDPConnection>}
 */
export async function connectCDP(url) {
    const ws = new WebSocket(url);
    await new Promise((resolve, reject) => {
        ws.on('open', resolve);
        ws.on('error', reject);
    });

    let idCounter = 1;
    /** @type {Map<number, {resolve: Function, reject: Function, timeoutId: ReturnType<typeof setTimeout>}>} */
    const pendingCalls = new Map();
    /** @type {Array<{id: number, name: string, origin: string}>} */
    const contexts = [];
    /** @type {Map<string, Set<(params: any) => void>>} */
    const eventListeners = new Map();

    // Single centralized message handler
    ws.on('message', (msg) => {
        try {
            const data = JSON.parse(/** @type {string} */(msg.toString()));

            if (data.id !== undefined && pendingCalls.has(data.id)) {
                const { resolve, reject, timeoutId } = pendingCalls.get(data.id);
                clearTimeout(timeoutId);
                pendingCalls.delete(data.id);
                if (data.error) reject(data.error);
                else resolve(data.result);
            }

            if (data.method === 'Runtime.executionContextCreated') {
                contexts.push(data.params.context);
            } else if (data.method === 'Runtime.executionContextDestroyed') {
                const id = data.params.executionContextId;
                const idx = contexts.findIndex(c => c.id === id);
                if (idx !== -1) contexts.splice(idx, 1);
            } else if (data.method === 'Runtime.executionContextsCleared') {
                contexts.length = 0;
            }

            if (data.method && eventListeners.has(data.method)) {
                for (const handler of eventListeners.get(data.method) || []) {
                    try {
                        handler(data.params);
                    } catch (_) {
                        // Ignore listener errors to preserve the CDP connection.
                    }
                }
            }
        } catch (_) { /* malformed message */ }
    });

    /** @type {(method: string, params?: object) => Promise<any>} */
    const call = (method, params) => new Promise((resolve, reject) => {
        const id = idCounter++;
        const timeoutId = setTimeout(() => {
            if (pendingCalls.has(id)) {
                pendingCalls.delete(id);
                reject(new Error(`CDP call ${method} timed out after ${CDP_CALL_TIMEOUT}ms`));
            }
        }, CDP_CALL_TIMEOUT);

        pendingCalls.set(id, { resolve, reject, timeoutId });
        ws.send(JSON.stringify({ id, method, params }));
    });

    /**
     * @param {string} event
     * @param {(params: any) => void} handler
     */
    const on = (event, handler) => {
        if (!eventListeners.has(event)) {
            eventListeners.set(event, new Set());
        }
        eventListeners.get(event)?.add(handler);
    };

    /**
     * @param {string} event
     * @param {(params: any) => void} handler
     */
    const off = (event, handler) => {
        eventListeners.get(event)?.delete(handler);
    };

    await call('Runtime.enable', {});
    await new Promise(r => setTimeout(r, 1000));

    return { ws, call, contexts, on, off };
}

/**
 * Initialize CDP connection — discover and connect.
 * Updates shared state with the new connection.
 *
 * @returns {Promise<import('../state.js').CDPConnection>}
 */
export async function initCDP() {
    console.log('🔍 Discovering Antigravity CDP endpoint...');
    const cdpInfo = await discoverCDP();
    console.log(`✅ Found Antigravity on port ${cdpInfo.port} `);

    console.log('🔌 Connecting to CDP...');
    const conn = await connectCDP(cdpInfo.url);
    state.setCdpConnection(conn);
    console.log(`✅ Connected! Found ${conn.contexts.length} execution contexts\n`);
    return conn;
}
